-- Import games from the owner's sheet, priced at the PS Store India regular price (checked 2026-10-30).
-- Upserts by slug; Secondary prices are cleared, set them in Admin -> Products.
on conflict (slug) do update set
  title = excluded.title,
  description = excluded.description,
  category = excluded.category,
  platforms = excluded.platforms,
  price = excluded.price,
  compare_at_price = null,
  secondary_price = null,
  is_featured = excluded.is_featured,
  is_active = true;

-- Not on the sheet
update public.products set is_active = false where slug = 'gran-turismo-7';

select count(*) filter (where is_active) as active_games from public.products where category = 'playstation-games';
